using ModelContextProtocol.Server;
using System.Text.Json;

namespace McpHttpServer;

[McpServerResource(
    Uri = "config://app/settings",
    Name = "App Settings",
    Description = "Returns the current application configuration",
    MimeType = "application/json")]
public class ConfigResourceProvider
{
    public Task<ReadResourceResult> ReadAsync(
        RequestContext<ReadResourceRequestParams> context,
        CancellationToken cancellationToken)
    {
        var config = new
        {
            AppName = "MyMcpService",
            Version = "1.0.0",
            Environment = "production",
            Features = new { EnableCache = true, MaxRetries = 3 }
        };

        var json = JsonSerializer.Serialize(config, new JsonSerializerOptions
        {
            WriteIndented = true
        });

        return Task.FromResult(new ReadResourceResult
        {
            Contents =
            [
                new TextResourceContents
                {
                    Uri = "config://app/settings",
                    MimeType = "application/json",
                    Text = json
                }
            ]
        });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public static class ServerTools
{
    [McpServerTool, Description("Gets the current server status and uptime")]
    public static string GetStatus()
    {
        return $"Server is running. Uptime: {Environment.TickCount64 / 1000}s";
    }

    [McpServerTool, Description("Echoes back the provided message")]
    public static string Echo([Description("The message to echo")] string message)
    {
        return $"Echo: {message}";
    }
}

